INSERT INTO `recommendations` (`id`, `status`, `content`, `created_at`, `updated_at`) VALUES
	(1, 'Berat Kurang', 'Berikan ASI eksklusif (0-6 bulan).\nBerikan MPASI bergizi seimbang mulai usia 6 bulan.\nTingkatkan asupan protein.\nBerikan makanan 3 kali sehari dan camilan sehat.\nPantau pertumbuhan setiap bulan.\nKonsultasikan ke dokter atau ahli gizi.', '2026-07-28 18:45:07', '2026-07-28 18:45:07'),
	(2, 'Berat Normal', 'Pertahankan pola makan bergizi seimbang.\nBerikan buah dan sayur.\nTetap aktif.\nPemeriksaan rutin ke Posyandu.', '2026-07-28 18:45:07', '2026-07-28 18:45:07'),
	(3, 'Berat Berlebih', 'Kurangi makanan tinggi gula.\nKurangi makanan tinggi lemak.\nPerbanyak aktivitas fisik.\nBatasi screen time.\nKonsultasikan ke dokter.', '2026-07-28 18:45:07', '2026-07-28 18:45:07'),
	(4, 'Tinggi Kurang', 'Tingkatkan protein.\nTingkatkan kalsium.\nTingkatkan zinc.\nTidur cukup.\nPantau pertumbuhan.', '2026-07-28 18:45:07', '2026-07-28 18:45:07'),
	(5, 'Tinggi Normal', 'Pertahankan pola makan sehat.\nMinum susu.\nAktivitas fisik.', '2026-07-28 18:45:07', '2026-07-28 18:45:07'),
	(6, 'Tinggi Di Atas Rata-rata', 'Tidak memerlukan tindakan khusus bila proporsional.\nTetap pantau perkembangan.', '2026-07-28 18:45:07', '2026-07-28 18:45:07');
